import pathlib,os,sys,json,hashlib,base64,subprocess,time,traceback
P=pathlib.Path
root=P('/home/alex/work/pocket4-factory-v2-pidfd-rejection-control-01')
base=P('/home/alex/work/pocket4-metadata-generation-r8-20261104/native-owned-01/overlay-reconstruction-09')
candidate=base/'candidate-04'
def sha(b):return hashlib.sha256(b).hexdigest()
def put(p,b):
 fd=os.open(p,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o444)
 with os.fdopen(fd,'wb') as f:f.write(b);f.flush();os.fsync(f.fileno())
manifest=(base/'candidate-04-source-manifest.json').read_bytes()
assert sha(manifest)=='00a19fef1ca8e86a3da18eecfb16eedb41e9de55e2934b96987845fa8b749fbd'
pins=json.loads(manifest)['files']
names=['host-factory-v2/source/factory_main.cc','host-factory-v2/source/factory_context.cc','host-factory-v2/source/factory_context.h','engine/kernel_api/proc_maps_factory_wire.cc','engine/kernel_api/include/berberis/kernel_api/proc_maps_factory_protocol.h','engine/kernel_api/include/berberis/kernel_api/proc_maps_kernel_statfs.h']
before={n:sha((candidate/n).read_bytes()) for n in names}
assert all(v==pins[n] for n,v in before.items())
compiler=P('/usr/bin/x86_64-linux-gnu-g++-15')
assert sha(compiler.read_bytes())=='e6718f7e0c7d057c3ff77b550c603da9bc4030e3ede3c053705acce1293dbe4d'
src=base64.b64decode('')
assert sha(src)=='1ab026f372a40e1748dcee38d2b2b1eeaa091d422b0d3a901cd81abaa61ceaf2'
os.umask(0o077);root.mkdir(mode=0o700);put(root/'control.cc',src)
report={'schema':1,'scope':'actual ValidateSocket and Receive under owned Unix listener and sockets; no factory service, namespace or Android actions','source_sha256':sha(src),'candidate_manifest_sha256':sha(manifest),'source_inputs_before':before,'success':False,'commands':[]}
def run(name,argv,timeout):
 p=subprocess.run(argv,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=timeout,env={'PATH':'/usr/bin:/bin','LANG':'C','LC_ALL':'C'})
 put(root/(name+'.stdout'),p.stdout);put(root/(name+'.stderr'),p.stderr)
 report['commands'].append({'name':name,'argv':argv,'returncode':p.returncode,'stdout':p.stdout.decode(errors='replace'),'stderr':p.stderr.decode(errors='replace'),'stdout_sha256':sha(p.stdout),'stderr_sha256':sha(p.stderr)})
 return p
try:
 argv=[str(compiler),'-std=gnu++20','-O1','-Wall','-Wextra','-Werror','-I',str(candidate/'engine/kernel_api/include'),'-I',str(candidate/'host-factory-v2/source'),str(root/'control.cc'),str(candidate/'host-factory-v2/source/factory_context.cc'),str(candidate/'engine/kernel_api/proc_maps_factory_wire.cc'),'-o',str(root/'control')]
 p=run('compile',argv,60);assert p.returncode==0
 report['elf_sha256']=sha((root/'control').read_bytes())
 p=run('actual-control',[str(root/'control')],8)
 rows=[json.loads(x) for x in p.stdout.decode().splitlines()];report['observed_rows']=rows
 assert p.returncode==0 and rows[-1]['all_control_descriptors_closed'] is True
 assert rows[1]['case']=='ordinary' and rows[1]['fds_after_rights_destructor_delta']==0 and rows[1]['finding_reproduced'] is True
 assert rows[2]['case']=='passpidfd' and rows[2]['accepted_passpidfd']==1 and rows[2]['receive_errno']==71 and rows[2]['unowned_pidfds']==1 and rows[2]['finding_reproduced'] is True
 report['source_inputs_after']={n:sha((candidate/n).read_bytes()) for n in names}
 assert before==report['source_inputs_after']
 report['success']=True;report['actual_factory_rejection_leak_reproduced']=True
except BaseException as error:
 report['error']={'type':type(error).__name__,'message':str(error),'traceback':traceback.format_exc()}
finally:
 raw=(json.dumps(report,indent=2,sort_keys=True)+'\n').encode();put(root/'result.json',raw);root.chmod(0o755)
 print(json.dumps({'success':report['success'],'report':str(root/'result.json'),'bytes':len(raw),'sha256':sha(raw),'error':report.get('error'),'namespace_or_Android_actions':False}),flush=True)
sys.exit(0 if report['success'] else 1)
